from pathlib import Path
ROOT=Path.cwd()
FILES={
    'desktop/src/renderer/pages/PlatformStandardsPage.tsx': '/**\n * Read-only System Workflow Rule Registry view.\n * QUALITY_EXECUTION.md is the sole human normative entry; this page displays\n * the executable registry projection without re-summarising rules.\n */\nimport React, { useCallback, useEffect, useMemo, useState } from \'react\';\nimport { api } from \'../lib/api\';\n\ninterface Rule {\n  id: string;\n  name: string;\n  category: string;\n  level: \'P0\' | \'P1\' | \'P2\' | \'P3\';\n  status: string;\n  blocking: boolean;\n  summary: string;\n  details?: string[];\n  scenarios: string[];\n  consumers: string[];\n  dependencies: string[];\n  dependents: string[];\n  implementationRefs: string[];\n  parameterRefs: string[];\n  evidencePolicy?: string | null;\n  rulesetVersion: number;\n  source: string;\n}\n\nconst categoryLabel: Record<string, string> = {\n  governance: \'规则治理\', authority: \'事实权威\', architecture: \'小说架构\', context: \'上下文与连续性\',\n  generation: \'生成\', quality: \'质量 Gate\', repair: \'修复\', workflow: \'工作流/保存\', platform: \'平台参数\', learning: \'历史经验/策略学习\',\n};\nconst categoryOrder = Object.keys(categoryLabel);\nconst card: React.CSSProperties = { background: \'var(--color-bg-secondary,#fff)\', border: \'1px solid var(--color-border,#e5e7eb)\', borderRadius: 12, padding: \'14px 16px\', marginBottom: 10 };\nconst tag: React.CSSProperties = { fontSize: \'var(--font-size-xs)\', padding: \'2px 8px\', borderRadius: 999, background: \'rgba(96,165,250,.14)\' };\n\nconst PlatformStandardsPage: React.FC = () => {\n  const [rules, setRules] = useState<Rule[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [openId, setOpenId] = useState<string | null>(null);\n\n  const load = useCallback(() => {\n    setLoading(true); setError(null);\n    api.getWithRetry(\'/module-standards/rules\')\n      .then((res) => setRules((((res as any).data ?? res) as { rules?: Rule[] }).rules || []))\n      .catch((e: any) => { setRules([]); setError(e?.message || \'系统工作流规则读取失败\'); })\n      .finally(() => setLoading(false));\n  }, []);\n  useEffect(() => { load(); }, [load]);\n\n  const grouped = useMemo(() => categoryOrder.map((category) => ({\n    category,\n    rules: rules.filter((rule) => rule.category === category),\n  })).filter((group) => group.rules.length), [rules]);\n\n  if (loading) return <div style={{ padding: 32 }}>正在加载系统工作流规则…</div>;\n  const version = rules[0]?.rulesetVersion;\n  return (\n    <div style={{ maxWidth: 1080, margin: \'0 auto\', padding: \'28px 24px\' }}>\n      <div style={{ display: \'flex\', alignItems: \'center\', gap: 10, flexWrap: \'wrap\' }}>\n        <h1 style={{ margin: 0, fontSize: 22 }}>系统工作流规则</h1>\n        {version !== undefined && <span style={tag}>ruleset v{version}</span>}\n        <span style={{ ...tag, color: \'#16a34a\' }}>只读 · 全部作品共用</span>\n        <button onClick={load} style={{ marginLeft: \'auto\' }}>刷新</button>\n      </div>\n      <p style={{ color: \'var(--color-text-muted)\', lineHeight: 1.7 }}>\n        唯一规范入口：QUALITY_EXECUTION.md。下方按 Rule ID 展示机器执行镜像；分类和场景只是过滤视图，不拥有第二套规则。\n      </p>\n      {error && <div style={{ ...card, color: \'#b91c1c\' }}>{error}</div>}\n      {grouped.map((group) => (\n        <section key={group.category} style={{ marginTop: 24 }}>\n          <h2 style={{ fontSize: 16 }}>{categoryLabel[group.category] || group.category} · {group.rules.length}</h2>\n          {group.rules.map((rule) => {\n            const open = openId === rule.id;\n            return <div key={rule.id} style={card}>\n              <button type="button" onClick={() => setOpenId(open ? null : rule.id)} style={{ width: \'100%\', display: \'flex\', gap: 8, alignItems: \'center\', flexWrap: \'wrap\', border: 0, background: \'transparent\', textAlign: \'left\', cursor: \'pointer\' }}>\n                <code>{rule.id}</code><strong>{rule.name}</strong><span style={tag}>{rule.level}</span>\n                {rule.blocking && <span style={{ ...tag, color: \'#b91c1c\' }}>可阻断</span>}\n                <span style={{ marginLeft: \'auto\' }}>{open ? \'收起 ▲\' : \'展开 ▼\'}</span>\n              </button>\n              <p style={{ margin: \'10px 0 0\', lineHeight: 1.7 }}>{rule.summary}</p>\n              {open && <div style={{ marginTop: 12, paddingTop: 12, borderTop: \'1px solid var(--color-border)\' }}>\n                <p><b>适用场景：</b>{rule.scenarios.join(\' / \')}</p>\n                <p><b>消费者：</b>{rule.consumers.join(\' / \')}</p>\n                <p><b>依赖：</b>{rule.dependencies.length ? rule.dependencies.join(\' / \') : \'无\'}</p>\n                <p><b>受影响下游：</b>{rule.dependents.length ? rule.dependents.join(\' / \') : \'无\'}</p>\n                {rule.details && rule.details.length > 0 && <div><b>详细条款：</b><ul>{rule.details.map((detail) => <li key={detail}>{detail}</li>)}</ul></div>}\n                {rule.parameterRefs.length > 0 && <p><b>参数源：</b>{rule.parameterRefs.join(\' / \')}</p>}\n                {rule.evidencePolicy && <p><b>证据要求：</b>{rule.evidencePolicy}</p>}\n                <p style={{ overflowWrap: \'anywhere\' }}><b>实现：</b>{rule.implementationRefs.join(\' / \')}</p>\n              </div>}\n            </div>;\n          })}\n        </section>\n      ))}\n    </div>\n  );\n};\n\nexport default PlatformStandardsPage;\n',
    'server/src/chain/source-countdown-consistency.ts': "/**\n * Advisory risk scan for explicit, calculable countdown/deadline wording.\n * Rule owner: CTX-005. No story-specific nouns/mechanics are allowed here.\n * Raw prose has no stable fact identity, so this helper MUST NOT block by itself; it only surfaces arithmetic risk to the semantic Gate.\n */\nconst DIGITS: Record<string, number> = {\n  零: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9,\n};\n\nfunction count(raw: string): number {\n  if (/^\\d+$/.test(raw)) return Number(raw);\n  if (raw === '十') return 10;\n  const parts = raw.split('十');\n  if (parts.length === 2) {\n    const tens = parts[0] ? DIGITS[parts[0]] ?? 0 : 1;\n    const ones = parts[1] ? DIGITS[parts[1]] ?? 0 : 0;\n    return tens * 10 + ones;\n  }\n  return DIGITS[raw] ?? Number.NaN;\n}\n\nfunction clockHour(rawHour: string, period = ''): number {\n  const hour = count(rawHour);\n  if (!Number.isFinite(hour)) return Number.NaN;\n  if (/(下午|晚上)/.test(period) && hour < 12) return hour + 12;\n  if (/凌晨/.test(period) && hour === 12) return 0;\n  return hour;\n}\n\ninterface DeadlineClaim {\n  raw: string;\n  days: number;\n  hour: number;\n}\ninterface RemainingClaim { raw: string; hours: number }\ninterface CurrentClaim { raw: string; hour: number }\n\nconst NUMBER = '[一二两三四五六七八九十零\\\\d]+';\n\nfunction deadlineClaims(text: string): DeadlineClaim[] {\n  const re = new RegExp(`(${NUMBER})天后(?:的)?(凌晨|上午|早上|中午|下午|晚上)?(${NUMBER})点`, 'g');\n  return [...text.matchAll(re)].map((match) => ({\n    raw: match[0], days: count(match[1]), hour: clockHour(match[3], match[2] || ''),\n  })).filter((item) => Number.isFinite(item.days) && Number.isFinite(item.hour));\n}\n\nfunction remainingClaims(text: string): RemainingClaim[] {\n  const re = new RegExp(`(?:倒计时|剩余|还剩)[^。；\\\\n]{0,12}?(${NUMBER})小时|(${NUMBER})小时[^。；\\\\n]{0,12}?(?:倒计时|剩余|还剩)`, 'g');\n  return [...text.matchAll(re)].map((match) => ({\n    raw: match[0], hours: count(match[1] || match[2]),\n  })).filter((item) => Number.isFinite(item.hours));\n}\n\nfunction currentClaims(text: string): CurrentClaim[] {\n  const re = new RegExp(`(?:当前|现在|此时|当下)[^。；\\\\n]{0,20}?(凌晨|上午|早上|中午|下午|晚上)?(${NUMBER})点`, 'g');\n  return [...text.matchAll(re)].map((match) => ({\n    raw: match[0], hour: clockHour(match[2], match[1] || ''),\n  })).filter((item) => Number.isFinite(item.hour));\n}\n\ninterface StartedCountdownClaim { raw: string; elapsedDays: number; totalHours: number }\nfunction startedCountdownClaims(text: string): StartedCountdownClaim[] {\n  const re = new RegExp(`(${NUMBER})天前[^。；\\\\n]{0,100}?(${NUMBER})小时[^。；\\\\n]{0,20}?(?:倒计时)(?:启动|开始)`, 'g');\n  return [...text.matchAll(re)].map((match) => ({\n    raw: match[0], elapsedDays: count(match[1]), totalHours: count(match[2]),\n  })).filter((item) => Number.isFinite(item.elapsedDays) && Number.isFinite(item.totalHours));\n}\n\n/**\n * Raw-text advisory only. Uniqueness in a paragraph/document is not proof that two claims share\n * the same fact identity, so callers may log/surface this risk but must not throw a deterministic Gate.\n */\nexport function detectSourceCountdownRisk(worldContext: string, outlineContract: string): string | null {\n  const deadlines = deadlineClaims(outlineContract);\n  const remaining = remainingClaims(outlineContract);\n  const current = currentClaims(outlineContract);\n\n  if (deadlines.length === 1 && remaining.length === 1 && current.length === 1) {\n    const expected = deadlines[0].days * 24 + deadlines[0].hour - current[0].hour;\n    if (expected !== remaining[0].hours) {\n      return `资料源可计算时间风险：按“${current[0].raw}”到“${deadlines[0].raw}”计算为 ${expected} 小时，与“${remaining[0].raw}”不符；请先统一同一倒计时事实，正文尚未调用模型。`;\n    }\n  }\n\n  const started = startedCountdownClaims(worldContext);\n  if (started.length === 1 && deadlines.length === 1) {\n    const left = started[0].totalHours - started[0].elapsedDays * 24;\n    const future = deadlines[0].days * 24;\n    if (deadlines[0].hour === 0 && left !== future) {\n      return `资料源可计算时间风险：世界资料“${started[0].raw}”计算剩余 ${left} 小时，而章纲“${deadlines[0].raw}”表示至少 ${future} 小时；请先统一同一倒计时事实。`;\n    }\n  }\n  return null;\n}\n",
}
for rel,content in FILES.items():
    p=ROOT/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content,encoding="utf-8")
print(f"wrote {len(FILES)} files")
